def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    total_cd = 0
    total_dc = 0
    total_cc = 0
    total_dd = 0
    my_def_count = 0
    for me, opp in history:
        if me == 'C' and opp == 'C':
            total_cc += 1
        elif me == 'C' and opp == 'D':
            total_cd += 1
        elif me == 'D' and opp == 'C':
            total_dc += 1
        else:
            total_dd += 1
        if me == 'D':
            my_def_count += 1

    if total_cd >= 5:
        return 'D'

    last_me, last_opp = history[-1]

    if last_me == 'D' and last_opp == 'C':
        return 'D'

    if total_dc >= 2 and last_opp == 'C':
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if total_dc >= 2:
                return 'C'
            if total_cc > total_dd:
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'D'
        else:
            if my_def_count == 0:
                cc_streak = 0
                for i in range(n - 1, -1, -1):
                    if history[i][0] == 'C' and history[i][1] == 'C':
                        cc_streak += 1
                    else:
                        break
                if n >= 15 and cc_streak >= 5:
                    return 'D'
            return 'C'

    return 'C'
